const motherAgeReadings = {
  '18-24':'Ты строишь свою взрослую жизнь рядом с материнством. Ни один тип не обязывает ставить собственные планы на вечную паузу.',
  '25-34':'В твоём календаре могут спорить несколько больших дел жизни. Этот архетип описывает привычную реакцию, а не меру твоих сил.',
  '35-44':'Опыт помогает узнавать знакомые семейные сценарии; он не назначает тебя автоматическим ответственным за всё.',
  '45-54':'У тебя есть право менять планы и правила семьи: стаж материнства не делает заботу о себе роскошью.',
  '55+':'Твои интересы и границы не заканчиваются на семейном статусе, сколько бы лет ни было материнскому стажу.',
};
export function getMotherAgeReading(ageId, archetype){
  const band=motherAgeBands.find(item=>item.id===ageId);
  if(!band||!archetype)return null;
  return `В диапазоне ${band.label} архетип «${archetype.title}» — одна привычная стратегия, а не весь твой характер. ${motherAgeReadings[band.id]}`;
}

